#include <algorithm>
#include <array>
#include <cstdint>
#include <fstream>
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>

using Z = std::int64_t;
using U = std::uint64_t;
using Wide = __int128_t;
constexpr int D = 16;
using Vector = std::array<Z,D>;

struct Atom {
    int order, cofactor, cost;
    Vector center, representative;
};
struct Side {
    std::vector<int> ids;
    Wide mask = 0;
    int cost = 0;
    Vector phase{};
};
struct Metrics {
    U pairs = 0, common = 0, nodes = 0, edges = 0, leaves = 0, outside = 0, live = 0;
};
struct Input {
    int side, count;
    Z scale;
    Vector norms;
    std::array<Vector,D> mu, basis;
    std::vector<Atom> atoms;
};
using Rosters = std::array<std::vector<Side>,9>;

Z floor_div(Z x,Z y) {
    const Z q=x/y;
    return q - (x%y < 0);
}
template <class Row> void read_row(std::istream& in, Row& row) {
    for (auto& x:row) in>>x;
}
Input open(const char* filename) {
    std::ifstream in(filename);
    int dimension;
    Input data;
    in>>dimension>>data.side>>data.scale>>data.count;
    if(!in || dimension!=D || data.side!=2331 || data.scale<1
       || data.scale>(Z(1)<<40) || data.count<1 || data.count>=127)
        throw std::runtime_error("incompatible input header");
    read_row(in,data.norms);
    for(auto& row:data.mu) read_row(in,row);
    for(auto& row:data.basis) read_row(in,row);
    data.atoms.resize(data.count);
    for(auto& atom:data.atoms) {
        in>>atom.order>>atom.cofactor>>atom.cost;
        read_row(in,atom.center);
        read_row(in,atom.representative);
    }
    if (!in || *std::min_element(data.norms.begin(),data.norms.end())<=2*2331*2331
        || *std::max_element(data.norms.begin(),data.norms.end())>1000000000)
        throw std::runtime_error("truncated input or failed flatness");
    return data;
}
void make_sides(const Input& in, std::vector<Side>& out, int start, int left, const Side& current) {
    if (left==0) { out.push_back(current); return; }
    for (int i=start;i<in.count;++i) {
        const Atom& a=in.atoms[i];
        if (a.order>left) break;
        if (current.cost+a.cost>in.side) continue;
        Side next=current;
        next.ids.push_back(i);
        next.mask|=Wide(1)<<i;
        next.cost+=a.cost;
        for (int j=0;j<D;++j) next.phase[j]+=a.center[j];
        make_sides(in,out,i,left-a.order,next);
    }
}
void print_ids(const Input& in,const Side& side) {
    std::cout<<'[';
    bool first=true;
    for(int id:side.ids) {
        if(!first) std::cout<<',';
        first=false;
        std::cout<<in.atoms[id].cofactor;
    }
    std::cout<<']';
}
struct Search {
    const Input& in;
    const Side& plus;
    const Side& minus;
    Metrics& result;
    Vector phase{}, z{};

    void finish() {
        ++result.leaves;
        Vector u{};
        Z p=0,n=0;
        for(int j=0;j<D;++j) {
            Z w=0;
            for(int id:plus.ids) w+=in.atoms[id].representative[j];
            for(int id:minus.ids) w-=in.atoms[id].representative[j];
            for(int i=0;i<D;++i) w+=z[i]*in.basis[i][j];
            Z weight=17*(j+1)-1;
            if(w%weight!=0) throw std::runtime_error("off-grid leaf");
            u[j]=w/weight;
            p+=std::max<Z>(0,w);
            n+=std::max<Z>(0,-w);
        }
        if(p>in.side-plus.cost || n>in.side-minus.cost) {
            ++result.outside;
            return;
        }
        ++result.live;
        std::cout<<"{\"type\":\"survivor\",\"plus\":";
        print_ids(in,plus);
        std::cout<<",\"minus\":";
        print_ids(in,minus);
        std::cout<<",\"u\":[";
        for(int j=0;j<D;++j) std::cout<<(j?",":"")<<u[j];
        std::cout<<"],\"residual\":["<<in.side-plus.cost-p<<','<<in.side-minus.cost-n<<"]}\n";
    }
    void walk(int i, Wide room, Z error) {
        if (i<0) { finish(); return; }
        ++result.nodes;
        Wide center=phase[i];
        for (int j=i+1;j<D;++j) center+=Wide(z[j])*in.mu[j][i];
        if (center < -(Wide(1)<<57) || center > (Wide(1)<<57))
            throw std::runtime_error("center exceeds checked integer envelope");
        const Z lo=-floor_div(Z(center)+error,in.scale)-1;
        const Z hi=-floor_div(Z(center)-error,in.scale);
        if (hi-lo>3 || lo < -65536 || hi > 65536)
            throw std::runtime_error("coefficient outside checked integer envelope");
        for(Z c=lo;c<=hi;++c) {
            ++result.edges;
            Z distance=std::max<Z>(0,std::abs(Z(center)+c*in.scale)-error);
            if(distance>in.scale) continue;
            const Wide penalty=Wide(in.norms[i])*distance*distance;
            if(penalty>room) continue;
            z[i]=c;
            walk(i-1,room-penalty,error+std::abs(c));
        }
    }
    void solve() {
        for(int i=0;i<D;++i) phase[i]=plus.phase[i]-minus.phase[i];
        const Wide A=in.side-plus.cost,B=in.side-minus.cost;
        walk(D-1,(A*A+B*B)*in.scale*in.scale,plus.ids.size()+minus.ids.size());
    }
};
int main(int argc,char** argv) {
    if(argc!=4) return 2;
    auto in=open(argv[1]);
    int first=std::stoi(argv[2]),last=std::stoi(argv[3]);
    if(first<1 || last>16 || first>last) return 2;
    Rosters rosters;
    for(int i=0;i<=std::min(last,8);++i) {
        make_sides(in,rosters[i],0,i,Side{});
        std::cout<<"{\"type\":\"roster\",\"order\":"<<i<<",\"sides\":"<<rosters[i].size()<<"}\n";
    }
    for(int total=first;total<=last;++total) for(int a=std::max(0,total-8);a<=total/2;++a) {
        const int b=total-a;
        Metrics r;
        for(std::size_t i=0;i<rosters[a].size();++i) {
            const auto& x=rosters[a][i];
            for(std::size_t j=(a==b?i+1:0);j<rosters[b].size();++j) {
                const auto& y=rosters[b][j];
                if(x.mask&y.mask) { ++r.common; continue; }
                ++r.pairs;
                Search{in,x,y,r}.solve();
            }
        }
        std::cout<<"{\"type\":\"split\",\"split\":["<<a<<','<<b<<"],\"noncancelled\":"<<r.pairs
                 <<",\"common_skips\":"<<r.common<<",\"tree_nodes\":"<<r.nodes
                 <<",\"visited_edges\":"<<r.edges<<",\"full_interval_leaves\":"<<r.leaves
                 <<",\"outside_original_budgets\":"<<r.outside<<",\"live\":"<<r.live<<"}\n"<<std::flush;
    }
}
